/* Strict hidden rule requirement */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #181425;
  --color-card: #262b44;
  --color-accent: #3a4466;
  --color-highlight: #ffcc00;
  --color-text: #f4f4f4;
  --color-dim: #8b9bb4;
  --pixel-border: 4px solid #181425;
  --pixel-shadow: 4px 4px 0px #000000;
  --pixel-font: "Courier New", Courier, monospace, system-ui;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--pixel-font);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  image-rendering: pixelated;
}

.app-container {
  width: 100%;
  max-width: 440px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.pixel-header .title {
  font-size: 24px;
  letter-spacing: 2px;
  text-align: center;
  color: var(--color-highlight);
  text-shadow: 2px 2px 0px #000000;
  font-weight: 800;
}

.pixel-card {
  background-color: var(--color-card);
  border: var(--pixel-border);
  box-shadow: var(--pixel-shadow);
  width: 100%;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.speaker-roster {
  background-color: var(--color-bg);
  border: 2px solid var(--color-accent);
  padding: 12px;
}

.roster-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.roster-item {
  padding: 8px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 18px;
  font-weight: bold;
  color: var(--color-dim);
  background-color: transparent;
  border: 2px solid transparent;
}

.roster-item.active {
  background-color: var(--color-accent);
  color: var(--color-highlight);
  border: 2px solid var(--color-highlight);
  box-shadow: 2px 2px 0px #000000;
}

.roster-item.done {
  text-decoration: line-through;
  opacity: 0.5;
}

.timer-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.timer-display-box {
  background-color: var(--color-bg);
  border: var(--pixel-border);
  box-shadow: inset 2px 2px 0px #000000;
  padding: 16px;
  width: 100%;
  text-align: center;
}

.timer-digits {
  font-size: 54px;
  font-weight: 900;
  letter-spacing: 4px;
  color: var(--color-text);
  line-height: 1;
}

.status-banner {
  font-size: 22px;
  font-weight: bold;
  color: var(--color-highlight);
  text-align: center;
  padding: 8px 16px;
  background-color: var(--color-accent);
  border: 2px solid var(--color-highlight);
  width: 100%;
}

.controls-panel {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.pixel-btn {
  flex: 1;
  font-family: var(--pixel-font);
  font-size: 18px;
  font-weight: bold;
  padding: 12px 16px;
  border: 3px solid #000000;
  box-shadow: 3px 3px 0px #000000;
  cursor: pointer;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--color-highlight);
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px #000000;
}

.btn-primary {
  background-color: var(--color-highlight);
  color: #181425;
}

.btn-primary:hover:not(:disabled) {
  filter: brightness(1.1);
}

.btn-secondary {
  background-color: var(--color-accent);
  color: var(--color-text);
}

.btn-secondary:hover:not(:disabled) {
  filter: brightness(1.15);
}

.pixel-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

@media (max-width: 360px) {
  .pixel-card {
    padding: 16px;
  }
  .timer-digits {
    font-size: 44px;
  }
  .pixel-btn {
    font-size: 16px;
    padding: 10px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const PARTICIPANTS = ['Alice', 'Bob', 'Charlie', 'Diana'];
  const SECONDS_PER_PERSON = 90;

  let currentIndex = 0;
  let remainingSeconds = SECONDS_PER_PERSON;
  let timerInterval = null;
  let isOver = false;

  const rosterList = document.getElementById('roster-list');
  const timerDisplay = document.getElementById('timer-display');
  const statusBanner = document.getElementById('status-banner');
  const btnNext = document.getElementById('btn-next');
  const btnReset = document.getElementById('btn-reset');

  function formatTime(totalSeconds) {
    const m = Math.floor(totalSeconds / 60);
    const s = totalSeconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  }

  function renderRoster() {
    rosterList.innerHTML = '';
    PARTICIPANTS.forEach((name, index) => {
      const li = document.createElement('li');
      li.className = 'roster-item';

      if (!isOver && index === currentIndex) {
        li.classList.add('active');
        li.setAttribute('aria-current', 'step');
      } else if (index < currentIndex || isOver) {
        li.classList.add('done');
      }

      const nameSpan = document.createElement('span');
      nameSpan.textContent = `${index + 1}. ${name}`;
      li.appendChild(nameSpan);

      if (!isOver && index === currentIndex) {
        const badge = document.createElement('span');
        badge.textContent = '◀';
        li.appendChild(badge);
      }

      rosterList.appendChild(li);
    });
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(remainingSeconds);
  }

  function advanceToNext() {
    if (isOver) return;

    if (currentIndex < PARTICIPANTS.length - 1) {
      currentIndex += 1;
      remainingSeconds = SECONDS_PER_PERSON;
      updateDisplay();
      renderRoster();
    } else {
      finishStandup();
    }
  }

  function finishStandup() {
    clearInterval(timerInterval);
    timerInterval = null;
    isOver = true;
    remainingSeconds = 0;
    updateDisplay();
    renderRoster();
    statusBanner.hidden = false;
    btnNext.disabled = true;
  }

  function startTimer() {
    clearInterval(timerInterval);
    timerInterval = setInterval(() => {
      if (remainingSeconds > 0) {
        remainingSeconds -= 1;
        updateDisplay();
      } else {
        advanceToNext();
      }
    }, 1000);
  }

  function resetStandup() {
    clearInterval(timerInterval);
    timerInterval = null;
    currentIndex = 0;
    remainingSeconds = SECONDS_PER_PERSON;
    isOver = false;
    statusBanner.hidden = true;
    btnNext.disabled = false;
    updateDisplay();
    renderRoster();
    startTimer();
  }

  btnNext.addEventListener('click', () => {
    advanceToNext();
  });

  btnReset.addEventListener('click', () => {
    resetStandup();
  });

  document.addEventListener('keydown', (event) => {
    if (event.code === 'Space' && event.target === document.body) {
      event.preventDefault();
      advanceToNext();
    }
  });

  // Initialize
  updateDisplay();
  renderRoster();
  startTimer();
});
